// Embeds art/*.svg and the manifest into src/artdata.js so the game needs no network and works from file://.
const fs = require('fs'); const path = require('path');
const art = path.join(__dirname, '..', 'art'); const manifest = JSON.parse(fs.readFileSync(path.join(art, 'manifest.json'), 'utf8'));
const svgs = {};
for (const name of Object.keys(manifest)) svgs[name] = fs.readFileSync(path.join(art, name + '.svg'), 'utf8').replace(/\n+$/, '').replace(/>\s+</g, '><');
const js = `// Generated by tools/bundle-art.js from art/*.svg — do not edit by hand; edit tools/art/*.js and rerun make-art + bundle-art.\nconst ART_META = ${JSON.stringify(manifest)};\nconst ART_SVGS = ${JSON.stringify(svgs)};\n`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'artdata.js'), js);
console.log(`bundled ${Object.keys(svgs).length} assets (${(js.length / 1024).toFixed(0)} KB) into src/artdata.js`);
